(6015898, 881023, 39679, '<td valign="top">This is a nice shot but I''m not finding a clear subject.  I find my eye desperately looking for something to focus on and not finding it.  Maybe zooming more tightly on the brown bit of land towards the left would make it more prominent and made the image stronger.</td>', 'This is a nice shot but I''m not finding a clear subject.  I find my eye desperately looking for something to focus on and not finding it.  Maybe zooming more tightly on the brown bit of land towards the left would make it more prominent and made the image stronger.', '2010-05-19 11:53:04.000000', NULL, 1),
(6015905, 881719, 39679, '<td valign="top">You''ve done a really nice job of using black and white to convey a feeling of lack of space.  Black and white is often employed for no purpose but in this case it was a good choice.</td>', 'You''ve done a really nice job of using black and white to convey a feeling of lack of space.  Black and white is often employed for no purpose but in this case it was a good choice.', '2010-05-19 11:54:35.000000', NULL, 1),
(6015907, 881338, 93756, '<td valign="top">Nice shot and sentiment but as far as bokeh it''s a little too bright to be appealing to my eye.</td>', 'Nice shot and sentiment but as far as bokeh it''s a little too bright to be appealing to my eye.', '2010-05-19 11:54:54.000000', NULL, 1),
(6015921, 881572, 86090, '<td valign="top">I Love it!!!</td>', 'I Love it!!!', '2010-05-19 11:58:49.000000', NULL, 1),
(6015925, 882053, 39679, '<td valign="top">You''ve done a really great job of controlling depth of field yet keeping enough detail to make this shot really interesting.  Nicely done.</td>', 'You''ve done a really great job of controlling depth of field yet keeping enough detail to make this shot really interesting.  Nicely done.', '2010-05-19 11:59:41.000000', NULL, 1),
