(6017435, 882441, 114225, '<td valign="top">Nice title for this photo. Seems like there is a lot of noise, unfortunately.</td>', 'Nice title for this photo. Seems like there is a lot of noise, unfortunately.', '2010-05-19 22:17:59.000000', NULL, 1),
(6017446, 882659, 96751, '<td valign="top">I like this dark and moody take on bokeh.  There may be just too much negative space on the right</td>', 'I like this dark and moody take on bokeh.  There may be just too much negative space on the right', '2010-05-19 22:22:15.000000', NULL, 1),
