(6017947, 881900, 108580, '<td valign="top">This is extremely creative. Sharp and appealing. Great take on the challenge spirit. In the line of one other shot, the champagne bokeh shot. Creativity 10. Execution 10.</td>', 'This is extremely creative. Sharp and appealing. Great take on the challenge spirit. In the line of one other shot, the champagne bokeh shot. Creativity 10. Execution 10.', '2010-05-20 04:44:32.000000', NULL, 1),
(6017948, 882291, 108580, '<td valign="top">Just magnificent. The bokeh makes him pop and the colours of insect, flower and bokeh are perfectly complimentary. Focus is excellent. We will never know if its dew or spray but if it''s spray then he was either to cold to move or very patient! 10</td>', 'Just magnificent. The bokeh makes him pop and the colours of insect, flower and bokeh are perfectly complimentary. Focus is excellent. We will never know if its dew or spray but if it''s spray then he was either to cold to move or very patient! 10', '2010-05-20 04:47:04.000000', NULL, 1),
