(6018303, 882680, 17507, '<td valign="top">Good use of shallow DOF. Strong tones. There''s some tension in your image created by the fact that the sharpest areas are at the tips of the leaves but the leading lines take the eye straight to the blurry areas.</td>', 'Good use of shallow DOF. Strong tones. There''s some tension in your image created by the fact that the sharpest areas are at the tips of the leaves but the leading lines take the eye straight to the blurry areas.', '2010-05-20 11:54:22.000000', NULL, 1),
(6018305, 883445, 17507, '<td valign="top">Cute kid. But that''s all I really see here. The OOF background adds nothing to the image and the kid isn''t doing anything except being cute. I reached my lifetime quota of cute-kid images years ago.</td>', 'Cute kid. But that''s all I really see here. The OOF background adds nothing to the image and the kid isn''t doing anything except being cute. I reached my lifetime quota of cute-kid images years ago.', '2010-05-20 11:56:24.000000', NULL, 1),
(6018307, 883208, 17507, '<td valign="top">Impressive. You''ve managed to make the blurred areas appear sharper than the unblurred areas. Whiterook would be proud.</td>', 'Impressive. You''ve managed to make the blurred areas appear sharper than the unblurred areas. Whiterook would be proud.', '2010-05-20 11:58:39.000000', NULL, 1),
