(6020919, 881203, 76335, '<td valign="top">This is gorgeous. I like your placement of the flower. The bokeh-filled negative space has lots of impact.</td>', 'This is gorgeous. I like your placement of the flower. The bokeh-filled negative space has lots of impact.', '2010-05-22 11:54:10.000000', NULL, 1),
(6020920, 883048, 76335, '<td valign="top">Great use of that narrow sliver of focus. Feels like he''s emerging from the depths.</td>', 'Great use of that narrow sliver of focus. Feels like he''s emerging from the depths.', '2010-05-22 11:55:00.000000', NULL, 1),
(6020922, 883652, 76335, '<td valign="top">The bokeh is good, the warm earthy colors are great!</td>', 'The bokeh is good, the warm earthy colors are great!', '2010-05-22 11:55:18.000000', NULL, 1),
(6020924, 882477, 76335, '<td valign="top">Fabulous use of DOF. Nice job with the lighting too. Seems like it would have been easy to blow some highlights here.</td>', 'Fabulous use of DOF. Nice job with the lighting too. Seems like it would have been easy to blow some highlights here.', '2010-05-22 11:56:09.000000', NULL, 1),
(6020925, 882872, 76335, '<td valign="top">Great idea. I do wish the image in the LCD were a bit clearer though. The bokeh is excellent.</td>', 'Great idea. I do wish the image in the LCD were a bit clearer though. The bokeh is excellent.', '2010-05-22 11:56:52.000000', NULL, 1),
(6020927, 882654, 76335, '<td valign="top">Absolutely fabulous. A top pick from me.</td>', 'Absolutely fabulous. A top pick from me.', '2010-05-22 11:57:31.000000', NULL, 1),
(6020931, 882861, 101668, '<td valign="top">very clever.</td>', 'very clever.', '2010-05-22 12:06:31.000000', NULL, 1),
