(6020939, 883202, 76335, '<td valign="top">Very nice, though something is lost in the blown highlights. I do like the bold colors.</td>', 'Very nice, though something is lost in the blown highlights. I do like the bold colors.', '2010-05-22 12:14:17.000000', NULL, 1),
(6021062, 881553, 47852, '<td valign="top">A nice conversion to b/w.  The blur looks as if it was created during post processing, which works nicely for isolating the subject, but doesn''t really seem to fit with the spirit of the challenge.</td>', 'A nice conversion to b/w.  The blur looks as if it was created during post processing, which works nicely for isolating the subject, but doesn''t really seem to fit with the spirit of the challenge.', '2010-05-22 16:16:51.000000', NULL, 1),
