(6021134, 883252, 111808, '<td valign="top">Absolutely superb &amp; imaginative take. I love this!</td>', 'Absolutely superb & imaginative take. I love this!', '2010-05-22 17:52:32.000000', NULL, 1),
(6021136, 882326, 19914, '<td valign="top">Gentle touch... my ten is for you.</td>', 'Gentle touch... my ten is for you.', '2010-05-22 17:54:26.000000', NULL, 1),
