(6021158, 880949, 111808, '<td valign="top">What an unusual coloured bird. This is an excellent &amp; evocative capture.<br/>The little ones hungry &amp; trusting and Mother taking care. One of my favourites in this challenge.</td>', 'What an unusual coloured bird. This is an excellent & evocative capture.The little ones hungry & trusting and Mother taking care. One of my favourites in this challenge.', '2010-05-22 18:11:24.000000', NULL, 1),
(6021176, 881338, 111808, '<td valign="top">It is so sad looking at this. 24 years of Life, gone too soon without living to his full potential, and fighting in a seemingly endless war in a distant land. Respectful capture, and never forget how many rows there are behind Joshua. Thank you for sharing your vision. The statement within the photograph needs to be said.</td>', 'It is so sad looking at this. 24 years of Life, gone too soon without living to his full potential, and fighting in a seemingly endless war in a distant land. Respectful capture, and never forget how many rows there are behind Joshua. Thank you for sharing your vision. The statement within the photograph needs to be said.', '2010-05-22 18:29:33.000000', NULL, 1),
(6021177, 882940, 111773, '<td valign="top">Very nice capture of just one ring!</td>', 'Very nice capture of just one ring!', '2010-05-22 18:30:13.000000', NULL, 1),
(6021179, 883592, 111773, '<td valign="top">Amazing clarity on such a small insect!</td>', 'Amazing clarity on such a small insect!', '2010-05-22 18:31:08.000000', NULL, 1),
(6021181, 883652, 111773, '<td valign="top">Beautiful orange tones!</td>', 'Beautiful orange tones!', '2010-05-22 18:33:07.000000', NULL, 1),
