(6021184, 883159, 61788, '<td valign="top">Very nice simple composition - simplicity I thik is strong part of it. Would have been stronger if glass jar/bottle was against darker background to make more accent on it''s color and diffrentiate from background more. Bokeh as I understand it is not strong. Good work.</td>', 'Very nice simple composition - simplicity I thik is strong part of it. Would have been stronger if glass jar/bottle was against darker background to make more accent on it''s color and diffrentiate from background more. Bokeh as I understand it is not strong. Good work.', '2010-05-22 18:37:01.000000', NULL, 1),
(6021185, 881335, 111773, '<td valign="top">Nice pic! It''s got an almost "alien" vibe to it!</td>', 'Nice pic! It''s got an almost "alien" vibe to it!', '2010-05-22 18:37:47.000000', NULL, 1),
(6021187, 883618, 111773, '<td valign="top">Not sure what I''m looking at? Was thinking that something should be in focus in the foreground for this challenge.</td>', 'Not sure what I''m looking at? Was thinking that something should be in focus in the foreground for this challenge.', '2010-05-22 18:41:11.000000', NULL, 1),
