(6022856, 882505, 85849, '<td valign="top">quite nice!</td>', 'quite nice!', '2010-05-23 23:34:40.000000', NULL, 1),
(6022859, 883611, 85849, '<td valign="top">Could have been a bit more in the DOF. Nice subject and bokeh!</td>', 'Could have been a bit more in the DOF. Nice subject and bokeh!', '2010-05-23 23:36:25.000000', NULL, 1),
(6022863, 882940, 85849, '<td valign="top">A really neat idea. The main subject is a bit too small though.</td>', 'A really neat idea. The main subject is a bit too small though.', '2010-05-23 23:37:45.000000', NULL, 1),
(6022864, 883417, 85849, '<td valign="top">to me the full flower needed to be in the DOF.</td>', 'to me the full flower needed to be in the DOF.', '2010-05-23 23:38:40.000000', NULL, 1),
(6022870, 882689, 85849, '<td valign="top">There could be less detail in the OOF area. Very sharp image and interesting subject!</td>', 'There could be less detail in the OOF area. Very sharp image and interesting subject!', '2010-05-23 23:40:24.000000', NULL, 1),
(6022874, 882053, 85849, '<td valign="top">This is a nice shot! I find it more of a DOF shot than bokeh though. The OOF areas don''t add to the main subject.</td>', 'This is a nice shot! I find it more of a DOF shot than bokeh though. The OOF areas don''t add to the main subject.', '2010-05-23 23:42:07.000000', NULL, 1),
(6022875, 882364, 85849, '<td valign="top">nice bokeh</td>', 'nice bokeh', '2010-05-23 23:42:56.000000', NULL, 1),
(6022877, 883620, 85849, '<td valign="top">Nice and sharp! The eyes are great and the bokeh above the head is quite nice!</td>', 'Nice and sharp! The eyes are great and the bokeh above the head is quite nice!', '2010-05-23 23:44:16.000000', NULL, 1),
(6022880, 882410, 85849, '<td valign="top">Not an interesting subject, but nice bokeh!</td>', 'Not an interesting subject, but nice bokeh!', '2010-05-23 23:45:24.000000', NULL, 1),
(6022889, 881142, 85849, '<td valign="top">It''s too bad about the big dark patch. The squirrel in nice and sharp and has an interesting pose.</td>', 'It''s too bad about the big dark patch. The squirrel in nice and sharp and has an interesting pose.', '2010-05-23 23:47:14.000000', NULL, 1),
(6022898, 883477, 85849, '<td valign="top">There have been a lot of grass shots with too little or nothing interesting in the DOF. Some may consider this a bit busy, but I find it quite interesting! I love the bokeh and I could see this hanging on  wall!</td>', 'There have been a lot of grass shots with too little or nothing interesting in the DOF. Some may consider this a bit busy, but I find it quite interesting! I love the bokeh and I could see this hanging on  wall!', '2010-05-23 23:51:02.000000', NULL, 1),
(6022903, 882881, 85849, '<td valign="top">DOF and bokeh - nice!</td>', 'DOF and bokeh - nice!', '2010-05-23 23:52:36.000000', NULL, 1),
(6022908, 882555, 85849, '<td valign="top">The red at the bottom is distracting. I can easily identify this as a hair brush. I find it would have been more striking if it were cropped above the red. Still a nice shot and interesting bokeh!</td>', 'The red at the bottom is distracting. I can easily identify this as a hair brush. I find it would have been more striking if it were cropped above the red. Still a nice shot and interesting bokeh!', '2010-05-23 23:55:39.000000', NULL, 1),
(6022909, 882563, 85849, '<td valign="top">a perfect title...</td>', 'a perfect title...', '2010-05-23 23:56:28.000000', NULL, 1),
(6022910, 881529, 85849, '<td valign="top">I hate to be picky, but to me this is a DOF shot rather than bokeh. A very nice shot though.</td>', 'I hate to be picky, but to me this is a DOF shot rather than bokeh. A very nice shot though.', '2010-05-23 23:57:31.000000', NULL, 1),
(6022915, 883353, 85849, '<td valign="top">I''ve only seen one shot like this that has worked for me. The main subject is too much in and out of the DOF and it''s not interesting for me.</td>', 'I''ve only seen one shot like this that has worked for me. The main subject is too much in and out of the DOF and it''s not interesting for me.', '2010-05-24 00:00:10.000000', NULL, 1),
(6022920, 883631, 85849, '<td valign="top">The bokeh should be making the main subject pop out of the picture. I''m not seeing that here. Perhaps a bit brighter and more of the flower in the DOF.</td>', 'The bokeh should be making the main subject pop out of the picture. I''m not seeing that here. Perhaps a bit brighter and more of the flower in the DOF.', '2010-05-24 00:02:57.000000', NULL, 1),
(6022924, 881057, 85849, '<td valign="top">WOW</td>', 'WOW', '2010-05-24 00:03:38.000000', NULL, 1),
