(6022949, 883238, 85849, '<td valign="top">Not the most interesting bokeh, BUT! It does EXACTLY what it''s supposed to do. It makes the flower pop out of the shot. The DOF is almost perfect! Excellent shot!</td>', 'Not the most interesting bokeh, BUT! It does EXACTLY what it''s supposed to do. It makes the flower pop out of the shot. The DOF is almost perfect! Excellent shot!', '2010-05-24 00:11:46.000000', NULL, 1),
(6022958, 882095, 85849, '<td valign="top">Technically very good, but the subject holds very little interest for me.</td>', 'Technically very good, but the subject holds very little interest for me.', '2010-05-24 00:13:57.000000', NULL, 1),
(6022962, 882564, 85849, '<td valign="top">nice!</td>', 'nice!', '2010-05-24 00:15:02.000000', NULL, 1),
(6022973, 883381, 85849, '<td valign="top">Is it an optical illusion or does the glass seem really dirty toward the top. A neat idea and the bokeh works!</td>', 'Is it an optical illusion or does the glass seem really dirty toward the top. A neat idea and the bokeh works!', '2010-05-24 00:17:58.000000', NULL, 1),
(6022976, 882483, 85849, '<td valign="top">nice!</td>', 'nice!', '2010-05-24 00:18:33.000000', NULL, 1),
