(6026491, 883618, 93421, '<td valign="top">Love the simplicity of this shot!</td>', 'Love the simplicity of this shot!', '2010-05-25 23:03:39.000000', NULL, 1),
(6026507, 883143, 44877, '<td valign="top">Such a darling cat, but no bokeh. I won''t vote.</td>', 'Such a darling cat, but no bokeh. I won''t vote.', '2010-05-25 23:09:32.000000', NULL, 1),
(6026512, 881674, 44877, '<td valign="top">If you didn''t have that heavy frame around this beautiful image, I''d give you an 8. Nonetheless, it''s very good.</td>', 'If you didn''t have that heavy frame around this beautiful image, I''d give you an 8. Nonetheless, it''s very good.', '2010-05-25 23:10:50.000000', NULL, 1),
(6026594, 883092, 32011, '<td valign="top">My out-and-out favourite in this challenge.  Originally gave it a 9 and have just bumped it up a notch to 10.  Excellent bokeh and absolutely stunning image all round.  Well done... hope to see this ribbon.  Deserves the blue IMO.</td>', 'My out-and-out favourite in this challenge.  Originally gave it a 9 and have just bumped it up a notch to 10.  Excellent bokeh and absolutely stunning image all round.  Well done... hope to see this ribbon.  Deserves the blue IMO.', '2010-05-25 23:34:31.000000', NULL, 1),
(6026604, 882788, 100831, '<td valign="top">Beautiful. I wish I had a window scene like that.</td>', 'Beautiful. I wish I had a window scene like that.', '2010-05-25 23:36:54.000000', NULL, 1),
(6026605, 881459, 100831, '<td valign="top">Nice variety for the challenge. I like this.</td>', 'Nice variety for the challenge. I like this.', '2010-05-25 23:36:58.000000', NULL, 1),
(6026607, 882924, 100831, '<td valign="top">Beautiful color.</td>', 'Beautiful color.', '2010-05-25 23:37:04.000000', NULL, 1),
(6026608, 883639, 100831, '<td valign="top">Oh man this is great! The poor fishy having to look at all that!<br/>A+ from me for the creativity.</td>', 'Oh man this is great! The poor fishy having to look at all that!A+ from me for the creativity.', '2010-05-25 23:37:09.000000', NULL, 1),
(6026609, 883649, 100831, '<td valign="top">Nice abstract shapes, lines, and terrific colors - with the added bonus in the middle. Terrific!</td>', 'Nice abstract shapes, lines, and terrific colors - with the added bonus in the middle. Terrific!', '2010-05-25 23:37:15.000000', NULL, 1),
(6026612, 883447, 100831, '<td valign="top">love the contrast.</td>', 'love the contrast.', '2010-05-25 23:37:56.000000', NULL, 1),
(6026649, 883329, 47974, '<td valign="top">Would have been so much better if you had cropped out the white stuff at the top.</td>', 'Would have been so much better if you had cropped out the white stuff at the top.', '2010-05-25 23:49:17.000000', NULL, 1),
(6026687, 882534, 47974, '<td valign="top">I know the challenge was Bokeh but would have liked to see something in focus.</td>', 'I know the challenge was Bokeh but would have liked to see something in focus.', '2010-05-25 23:58:59.000000', NULL, 1),
(6026693, 882327, 47974, '<td valign="top">The blown highlights in the middle and lens flare really detract from the photo.  Also seems a little tilted to the right.</td>', 'The blown highlights in the middle and lens flare really detract from the photo.  Also seems a little tilted to the right.', '2010-05-25 23:59:41.000000', NULL, 1),
(6026694, 883095, 47974, '<td valign="top">While you got a pretty model the back ground is distracting and pleasing to your subject.</td>', 'While you got a pretty model the back ground is distracting and pleasing to your subject.', '2010-05-26 00:00:18.000000', NULL, 1),
(6026696, 883472, 47974, '<td valign="top">The blown highlights in the center really detract from what little bokeh you do have.</td>', 'The blown highlights in the center really detract from what little bokeh you do have.', '2010-05-26 00:00:50.000000', NULL, 1),
(6026700, 883097, 47974, '<td valign="top">While you have bokeh would have liked to see something in focus.  Photo is just distracting and kind find anything to hold my attention.</td>', 'While you have bokeh would have liked to see something in focus.  Photo is just distracting and kind find anything to hold my attention.', '2010-05-26 00:01:31.000000', NULL, 1),
(6026704, 883418, 47974, '<td valign="top">You don''t really have any bokeh, the areas that could hold bokeh are just solid black.  While it does isolate your subject you cropped to tightly for it to be effective.</td>', 'You don''t really have any bokeh, the areas that could hold bokeh are just solid black.  While it does isolate your subject you cropped to tightly for it to be effective.', '2010-05-26 00:02:32.000000', NULL, 1),
(6026707, 882931, 47974, '<td valign="top">While you have a nice blurred green background would have liked to see more of the subject so the bokeh could set it off.</td>', 'While you have a nice blurred green background would have liked to see more of the subject so the bokeh could set it off.', '2010-05-26 00:03:20.000000', NULL, 1),
(6026708, 883625, 47974, '<td valign="top">Photo is to hard to find out what is they subject / in focus.</td>', 'Photo is to hard to find out what is they subject / in focus.', '2010-05-26 00:03:47.000000', NULL, 1),
(6026714, 882325, 47974, '<td valign="top">While you have decent bokeh your subject is not sharp and detracts from the photo</td>', 'While you have decent bokeh your subject is not sharp and detracts from the photo', '2010-05-26 00:04:20.000000', NULL, 1),
(6026719, 882867, 47974, '<td valign="top">Maybe it would look better bigger but as it is there is no real subject to hold my interest.</td>', 'Maybe it would look better bigger but as it is there is no real subject to hold my interest.', '2010-05-26 00:04:57.000000', NULL, 1),
(6026723, 882782, 47974, '<td valign="top">Nice sharp photograph (may have over sharpened it), would have liked to see more of the pretty blue bokeh to set off the image better.</td>', 'Nice sharp photograph (may have over sharpened it), would have liked to see more of the pretty blue bokeh to set off the image better.', '2010-05-26 00:05:32.000000', NULL, 1),
(6026728, 882981, 47974, '<td valign="top">Looks more like a snap shot with a blurry background.  The subject just don''t stand out to me and I find the grass in the front a bit distracting.</td>', 'Looks more like a snap shot with a blurry background.  The subject just don''t stand out to me and I find the grass in the front a bit distracting.', '2010-05-26 00:06:22.000000', NULL, 1),
(6026731, 883498, 47974, '<td valign="top">Nice fake bokeh.  Yes I know you used some kind of filter to achieve the bokeh but I just don''t care for it.</td>', 'Nice fake bokeh.  Yes I know you used some kind of filter to achieve the bokeh but I just don''t care for it.', '2010-05-26 00:07:00.000000', NULL, 1),
(6026736, 881548, 47974, '<td valign="top">Interesting photograph.  The more I look at it the more it appeals to me.  The bokeh is pleasing to the eye and in a strange way helps bring your subject to life.</td>', 'Interesting photograph.  The more I look at it the more it appeals to me.  The bokeh is pleasing to the eye and in a strange way helps bring your subject to life.', '2010-05-26 00:08:17.000000', NULL, 1),
(6026742, 883018, 47974, '<td valign="top">While the outer leafs are out of focus it just don''t have bokeh to me.  Maybe a shallower DOF or a larger crop would have helped it.</td>', 'While the outer leafs are out of focus it just don''t have bokeh to me.  Maybe a shallower DOF or a larger crop would have helped it.', '2010-05-26 00:09:24.000000', NULL, 1),
(6026746, 883276, 47974, '<td valign="top">Nice photograph but the lighting is just not right.  But nice use of the bokeh to separate your two subjects.</td>', 'Nice photograph but the lighting is just not right.  But nice use of the bokeh to separate your two subjects.', '2010-05-26 00:10:09.000000', NULL, 1),
(6026749, 883581, 75618, '<td valign="top">It looks like there was some spot-editing done because of the areas that are in focus (i.e. the spot in right middle). But I''ll give you the benefit of the doubt.</td>', 'It looks like there was some spot-editing done because of the areas that are in focus (i.e. the spot in right middle). But I''ll give you the benefit of the doubt.', '2010-05-26 00:10:44.000000', NULL, 1),
(6026763, 882989, 75618, '<td valign="top">You mean after the <i>acid</i> rain?  =)<br/> <br/>Stunning colors, stands out among the 1820120192 other flower shots.</td>', 'You mean after the acid rain?  =) Stunning colors, stands out among the 1820120192 other flower shots.', '2010-05-26 00:12:58.000000', NULL, 1),
(6026813, 881414, 30861, '<td valign="top">Gosh, Stephen, sharpest image I ever seen from you. That''s the good news. The bad news? There ain''t much bokeh :-)</td>', 'Gosh, Stephen, sharpest image I ever seen from you. That''s the good news. The bad news? There ain''t much bokeh :-)', '2010-05-26 00:33:36.000000', NULL, 1),
